//! FieldEdge Rust core crate
//!
//! Provides the in-process vector store, sync orchestrator, conflict
//! resolution, and Write-Ahead Log for the FieldEdge offline-first
//! mobile AI platform.

#![allow(warnings)]
#![allow(clippy::needless_return)]

pub mod edge;
pub mod sync;
