pub mod crypto;
pub mod ffi;
pub mod embedding;
pub mod observability;

// UniFFI scaffolding is generated by build.rs (uniffi/field_edge.udl).
// The `uniffi` feature enables it; the public FFI surface is in `ffi::exports`.

use tracing_subscriber::EnvFilter;

/// Initialize logging. Idempotent; safe to call multiple times.
pub fn init_logging() {
    let _ = tracing_subscriber::fmt()
        .with_env_filter(
            EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new("info")),
        )
        .with_target(false)
        .try_init();
}
